// ===== TURN ENGINE =====
function advance(cost){if(G.over)return;cost=cost===undefined?100:cost;const p=G.p;rebuildOcc();let c=cost*100/(70+eff('spd')*6);if(p.aug&&p.charge<=0)c*=1.25;if(p.mount&&cost>=80&&RT.moving&&!p.aboard)c=c*110/MOUNTS[p.mount.s].spd;G.acc+=c;
 if(!p.fx.tstop){for(const m of RT.act.slice()){if(G.over)break;if(m.dead||L.cr.indexOf(m)<0)continue;m.en=(m.en||0)+c*spdOf(m)/100;let g=0;while(m.en>=100&&!G.over&&g++<4){m.en-=100;aiAct(m)}}}
 while(G.acc>=100&&!G.over){G.acc-=100;envTick()}
 if(RT.forceWait&&!G.over){const n=RT.forceWait;RT.forceWait=0;msg('You lose '+n+' turns.','bad');for(let i=0;i<n&&!G.over;i++)advance(100)}
 if(RT.later&&!G.over){const l=RT.later;RT.later=null;l.forEach(f=>f())}
 RT.arsonT=0;RT.moving=0;if(p.aboard){const v=vesselById(p.aboard);if(v){v.x=p.x;v.y=p.y}}realizeTick();rebuildOcc();computeFOV();if(G.turn%10===0)saveGame()}
function actWait(){advance(100)}
function toggleSneak(){G.p.sneak=!G.p.sneak;msg(G.p.sneak?'You move quietly. Slower, but harder to notice.':'You stop sneaking.','hint')}
function vesselById(id){return(G.vessels||[]).find(v=>v.id===id)}
function swimmable(d){return d.swim||d.water}
function actMove(dx,dy){const p=G.p;if(G.over)return null;if(p.fx.grabbed){if(chance(eff('str')*.1)){delete p.fx.grabbed;msg('You tear free!','good')}else{msg('You struggle in its grip.','bad');advance(100);return null}}if(p.dom>0&&chance(.45)){const d=pick(DIRS);dx=d[0];dy=d[1];msg('Your legs do not obey you.','bad')}
 const nx=p.x+dx,ny=p.y+dy;if(!inb(L,nx,ny))return null;const e=at(nx,ny);for(let i=0;i<8;i++)if(DIRS[i][0]===dx&&DIRS[i][1]===dy)p.face=i;
 if(e&&!isP(e)){if(e.ally||e.charm>0||e.tame&&!hostile(e,p)){swapWith(e,nx,ny);return null}if(hostile(e,p)||SP[e.s].tags.prey&&!e.tame){attackPlayerHit(e);return null}
  // softlock fix: friendly or neutral NPCs let you squeeze past
  if(!hostile(e,p)&&passC({s:e.s,x:p.x,y:p.y},p.x,p.y)!==null){if(SP[e.s].tags.talks&&!RT.bumpTalk){RT.bumpTalk=1;return{sheet:talkSheet(e)}}RT.bumpTalk=0;swapWith(e,nx,ny,true);return null}return{sheet:actionSheetFor(nx,ny)}}
 RT.bumpTalk=0;const d=tdef(nx,ny);const v=vesselAt(nx,ny);
 if(p.aboard){const mv=vesselById(p.aboard);if(v&&v!==mv){msg('Another vessel blocks the way.','warn');return null}if(swimmable(d)&&!d.p||d.water||d.ocean||d.icy&&false){if(d.icy){msg('Ice blocks the hull.','warn');return null}if(at(nx,ny)){return null}return sail(mv,nx,ny,dx,dy)}if(d.p||d.door){p.aboard=null;msg('You step ashore.','hint');const crew=disembarkCrew(mv);}else return null}
 else if(v&&!v.sunk){if(v.owner==='p'||v.free){boardVessel(v);return null}msg('That vessel is not yours.','warn');return null}
 if(d.k==='door'){tset(nx,ny,'dooropen');advance(60);return null}if(d.k==='locked'){msg('It is locked.','warn');return{tile:{x:nx,y:ny}}}if(d.gate){msg('The '+d.n+' is locked.','warn');return{tile:{x:nx,y:ny}}}if(d.seal){if(hasItem('sunder')){tset(nx,ny,'gateopen');msg('The seal reads the amulet. Stone grinds aside.','story');story('Opened the Sealed Gate.',4);advance(100)}else msg('A seal of black stone. It wants the Sundering Amulet, made from every sub-king\'s shard.','warn');return null}
 if(d.lava){msg('That is lava. You stop at the edge.','warn');return null}
 if(!d.p&&!d.swim){if(d.k==='sea'&&false){}if(d.chop||d.mine||d.waterSrc||d.store||d.forge||d.arcane||d.crys)return{tile:{x:nx,y:ny}};return null}
 if(p.mount&&d.swim&&!MOUNTS[p.mount.s].trample){msg('Your '+MOUNTS[p.mount.s].n+' refuses the deep water. Dismount to swim.','warn');return null}
 if(p.mount&&d.indoor&&MOUNTS[p.mount.s].trample){msg('Your '+MOUNTS[p.mount.s].n+' will not fit indoors.','warn');return null}
 if(d.swim&&!p.fx.waterwalk&&!p.swimOk){RT.swimAsk={x:nx,y:ny};return{sheet:{title:'Deep water',text:'Swimming soaks your powder and torches, and you can drown if you stay out too long. '+(tdef(nx,ny).ocean?'The open sea is dangerous without a boat.':''),options:[{label:'Swim',fn:()=>{p.swimOk=1;const r=actMove(dx,dy);p.swimOk=0;return r}},{label:'Stay on land',fn:()=>null}]}}}
 if(L.fire[IX(nx,ny)])msg('You step into the flames!','bad');
 p.x=nx;p.y=ny;G.stats.tiles++;let cost=100*(d.m||1);if(d.swim&&!p.fx.waterwalk){cost=220;if(p.torch>0){p.torch=0;msg('Your torch goes out.','warn')}if(!p.breath)msg('You swim.','warn');p.fx.wet={t:15};p.loaded=false}if(d.water)p.fx.wet={t:8};if(p.sneak)cost*=1.35;if(p.mount&&['vines','mangrove','reeds','bog','tar','drift'].includes(d.k))cost*=1.6;
 if(d.trap){if(d.k==='pit'){msg('You fall in a pit.','bad');hurt(p,3,null,'a pit');RT.forceWait=2}else if(d.k==='spikes'){hurt(p,8,null,'spikes');tset(nx,ny,'grass')}else if(d.k==='snare'){msg('A snare catches your ankle.','bad');RT.forceWait=3;tset(nx,ny,'grass')}}
 if(d.k==='tar'){msg('Tar drags at your feet.','warn');cost*=1.3}if(d.spiky)hurt(p,1,null,d.n);if(d.icy&&chance(.1)&&!p.mount){if(!at(nx+dx,ny+dy)&&tdef(nx+dx,ny+dy).p){p.x+=dx;p.y+=dy;msg('You slip on the ice.','warn')}}if(d.k==='thinice'&&chance(p.mount?.2:.015))meltTile(p.x,p.y);if(d.warm&&p.hp<p.mh&&chance(.4))p.hp++;if(d.vent&&chance(.3)){hurt(p,2,null,'steam');msg('A vent scalds you.','bad')}
 const a=p.eq.a&&idef(p.eq.a);let nr=p.sneak?1:(a&&a.noisy?7:p.mount?6:(['drift','sand','dune','shard'].includes(d.k)?5:4));noise(p.x,p.y,nr,'p');
 const its=L.items[IX(p.x,p.y)];if(its&&its.length){const coin=its.filter(i=>i.k==='coins');coin.forEach(c=>{giveItem(c);its.splice(its.indexOf(c),1)});if(its.length)msg('Here: '+its.slice(0,3).map(iname).join(', ')+(its.length>3?' and more':'')+'.','hint');else delete L.items[IX(p.x,p.y)]}
 if(L.tracks[IX(p.x,p.y)]&&L.tracks[IX(p.x,p.y)].s!=='p'&&chance(.15)){const tr=L.tracks[IX(p.x,p.y)];msg('Fresh '+SP[tr.s].n.toLowerCase()+' tracks.','hint')}
 RT.moving=1;advance(cost);return null}
function swapWith(e,nx,ny,squeeze){const p=G.p;const ox=p.x,oy=p.y;if(squeeze&&!passC(Object.assign({},e,{x:nx,y:ny}),ox,oy)&&!tdef(ox,oy).p){msg(cname(e)+' is in the way.','hint');return}p.x=nx;p.y=ny;RT.occ.delete(IX(nx,ny));e.x=ox;e.y=oy;RT.occ.set(IX(ox,oy),e);if(squeeze)msg('You squeeze past '+cname(e)+'.','');advance(100)}
function attackPlayerHit(t){const p=G.p;if(!hostile(t,p)&&SP[t.s].tags.person)crime('assault',t);meleeHit(p,t);if(p.fx.invis)delete p.fx.invis;advance(100)}
// ===== VESSELS =====
function newVessel(kind,x,y,owner){const v={id:++G.cid,kind,x,y,hp:kind==='raft'?30:90,mh:kind==='raft'?30:90,hold:[],cannons:kind==='longship'?0:0,crew:[],owner:owner||'p'};G.vessels.push(v);return v}
function boardVessel(v){const p=G.p;if(p.mount&&v.kind==='raft'){msg('A raft cannot carry your '+MOUNTS[p.mount.s].n+'.','warn');return}p.x=v.x;p.y=v.y;p.aboard=v.id;msg('You board your '+(v.kind==='raft'?'raft':'longship')+'. Steer onto water to sail; steer into land to step ashore.','good');const allies=L.cr.filter(c=>(c.ally||c.tame&&c.stay===0)&&dist(c.x,c.y,p.x,p.y)<=3);const cap=v.kind==='raft'?1:6;allies.slice(0,cap-(v.crew||[]).length).forEach(c=>{v.crew.push({s:c.s,hp:c.hp,name:c.name,mount:c.mount});const i=L.cr.indexOf(c);L.cr.splice(i,1);RT.occ.delete(IX(c.x,c.y))});if(v.crew.length)msg(v.crew.length+' companion'+(v.crew.length>1?'s come':' comes')+' aboard.','good');advance(100)}
function disembarkCrew(v){if(!v||!v.crew||!v.crew.length)return;const p=G.p;v.crew.slice().forEach(m=>{const sp=passableSpot(p.x,p.y,3);if(!sp)return;spawn(m.s,sp.x,sp.y,{ally:1,hp:m.hp,name:m.name,mount:m.mount});v.crew.splice(v.crew.indexOf(m),1)})}
function sail(v,nx,ny,dx,dy){const p=G.p;let cost=v.kind==='raft'?150:70;const wd=dx*G.wind.dx+dy*G.wind.dy;cost*=wd>0?.75:wd<0?1.35:1;if(G.wx.k==='gale')cost*=v.kind==='raft'?1.6:1.15;if(tdef(nx,ny).k==='reef'&&chance(.3)){v.hp-=v.kind==='raft'?3:2;msg('Coral scrapes the hull.','warn');checkSink(v)}p.x=nx;p.y=ny;v.x=nx;v.y=ny;const its=L.items[IX(nx,ny)];if(its&&its.length){its.forEach(i=>giveItem(i));delete L.items[IX(nx,ny)]}advance(cost);return null}
function checkSink(v){if(v.hp>0||v.sunk)return;v.sunk=1;const p=G.p;if(p.aboard===v.id){p.aboard=null;msg('Your '+v.kind+' breaks apart! You are in the water.','bad');story('Lost a '+v.kind+' at sea.',3);(v.crew||[]).forEach(m=>{const sp=waterSpot(p.x,p.y,2);if(sp)spawn(m.s,sp.x,sp.y,{ally:1,hp:m.hp})});if(v.kind==='longship'||chance(.5)){const r=newVessel('raft',p.x,p.y,'p');r.hp=Math.ceil(r.mh/2);p.aboard=r.id;msg('You haul yourself onto a raft lashed from the wreckage.','warn')}}v.hold.forEach(it=>addItem(L,v.x,v.y,it));G.vessels=G.vessels.filter(q=>q!==v)}
function vesselTick(){const p=G.p;if(!p.aboard)return;const v=vesselById(p.aboard);if(!v)return;const near=RT.act.filter(c=>dist(c.x,c.y,v.x,v.y)<=1&&hostile(c,p)&&(SP[c.s].tags.sea||SP[c.s].tags.ship));near.forEach(c=>{if(SP[c.s].tags.sea&&(SP[c.s].tags.huge||SP[c.s].hp>=60)&&chance(.4)){v.hp-=Math.ceil(SP[c.s].a/(v.kind==='longship'?4:3));if(chance(.4))msg(cname(c)+' slams into the hull!','bad');checkSink(v)}});(v.crew||[]).forEach(m=>{const t=near[0];if(t&&chance(.5)){hurt(t,SP[m.s].a+ri(0,2),G.p,'blow')}})}
function fireCannon(x,y){const p=G.p;const v=vesselById(p.aboard);if(!v||!v.cannons){msg('You have no cannon mounted.','warn');return}const ball=v.hold.find(i=>i.k==='cannonball')||null;const pw=v.hold.find(i=>i.k==='powder')||null;const useInv=!ball&&hasItem('cannonball')&&(pw||hasItem('powder')||hasItem('shot'));if(!ball&&!useInv){msg('Load cannonballs into the hold (or carry them).','warn');return}if(ball){ball.q--;if(ball.q<=0)v.hold.splice(v.hold.indexOf(ball),1)}else takeItem('cannonball');if(dist(p.x,p.y,x,y)>9){msg('Out of range.','warn');return}noise(p.x,p.y,20,'p');RT.fxq.push({type:'shot',x:p.x,y:p.y,x2:x,y2:y});msg('BOOM. Your cannon fires.','');const n=v.cannons;for(let k=0;k<n;k++){const tx=x+(k?ri(-1,1):0),ty=y+(k?ri(-1,1):0);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const e=at(tx+dx,ty+dy);if(e&&!isP(e))hurt(e,dx||dy?7:20,p,'cannonball');const d=tdef(tx+dx,ty+dy);if(d.f&&chance(.2))ignite(tx+dx,ty+dy,1);if((d.wall||d.door)&&!dx&&!dy&&chance(.4))tset(tx,ty,'rubble')}}advance(120)}
// ===== RIDING =====
function mountUp(c){const p=G.p;if(!SP[c.s].tags.mountable||!MOUNTS[c.s]){msg('You cannot ride that.','warn');return}if(!c.tame&&!c.ally){msg(cname(c)+' is not tame. Feed it until it trusts you, or buy one.','warn');return}if(p.aboard){msg('Not while aboard.','warn');return}p.mount={s:c.s,hp:c.hp,mh:c.mh,name:c.name};const i=L.cr.indexOf(c);L.cr.splice(i,1);RT.occ.delete(IX(c.x,c.y));p.x=c.x;p.y=c.y;msg('You climb onto the '+MOUNTS[c.s].n+'.','good');if(c.s==='elephant'||c.s==='warelephant'||c.s==='mammoth')story('Rode a '+MOUNTS[c.s].n+'.',1);advance(100)}
function dismount(){const p=G.p;if(!p.mount)return;const sp=passableSpot(p.x,p.y,2);if(!sp){msg('No room to dismount here.','warn');return}spawn(p.mount.s,sp.x,sp.y,{tame:1,stay:1,hp:p.mount.hp,mh:p.mount.mh,name:p.mount.name,job:'idle',myMount:1});msg('You dismount. Your '+MOUNTS[p.mount.s].n+' waits here.','');p.mount=null;advance(80)}
// ===== FISHING =====
function canFishAt(x,y){const d=tdef(x,y);return d.water||d.swim||d.icy&&d.under}
function fish(x,y){const p=G.p;const tool=p.inv.find(i=>idef(i).fishing)||(idef(p.eq.w).fishing?p.eq.w:null);if(!tool){msg('You need a fishing rod, net, or harpoon.','warn');return}const d=tdef(x,y);if(d.icy){if(d.k!=='thinice'&&d.k!=='seaice'&&d.k!=='ice'){msg('Too thick to fish through.','warn');return}msg('You cut a hole in the ice.','')}const bk=biomeKey(x,y);const ocean=d.ocean||d.k==='seaice';const se=seasonIdx();const h=dayFrac();let ch=.32+(idef(tool).fishing-1)*.12+eff('agi')*.015;if(se===0||se===2)ch+=.08;if(h<.18&&h>=.08||h>=.62&&h<.74)ch+=.1;if(typeof moonPhase==='function'&&moonPhase()===4)ch+=.08;if(raining())ch+=.05;if(se===3&&!d.icy)ch-=.1;noise(x,y,2,'p');
 let turns=ri(3,8);for(let i=0;i<turns&&!G.over;i++){advance(100);if(RT.hit){RT.hit=0;msg('You drop the line!','bad');return}}
 if(!chance(ch)){msg(pick(['Nothing bites.','A nibble, then nothing.','The fish are not interested.']),'');return}
 let pool;if(ocean)pool=[['cod',5],['tuna',3],['crab',3],['eel',2],['swordfish',1],['pearl',.6],['boot',1],['bottle',.6]];else if(['tundra','glacier','taiga'].includes(bk)||d.icy)pool=[['icefish',3],['salmon',4],['trout',3],['pike',2]];else if(['swamp','mangrove'].includes(bk))pool=[['catfish',4],['eel',3],['carp',2],['crab',1],['boot',1]];else pool=[['trout',4],['carp',4],['pike',2],['salmon',se===2?4:1],['catfish',2],['goldcarp',.15],['boot',1]];
 const k=wpick(pool);if(k==='bottle'){giveItem(mk('treasuremap'));msg('A bottle with a map inside!','good');return}const it=mk(k,idef(tool).fishing>=3&&chance(.5)?2:1);giveItem(it);msg('You land '+iname(it).toLowerCase()+'!','good');if(k==='goldcarp')story('Caught a golden carp.',2);G.stats.fish=(G.stats.fish||0)+1;gainXP(2);
 if(ocean&&isNight()&&chance(.06)){const sp=waterSpot(x+ri(-4,4),y+ri(-4,4),3);if(sp){spawn(pick(['shark','serpent']),sp.x,sp.y,{alert:2,wild:1,hunger:90});msg('Something large stirs beneath the water...','bad')}}}
// ===== COMBAT =====
function meleeHit(a,t){const dA=isP(a)?null:SP[a.s];const hit=hitChance(a,t);RT.fxq.push({type:'slash',x:t.x,y:t.y});if(!chance(hit/100)){if(isP(t)||isP(a)||visible(a.x,a.y))msg((isP(a)?'You miss ':cname(a)+' misses ')+(isP(t)?'you':cname(t))+'.');return false}
 let dm;if(isP(a)){const w=idef(a.eq.w);const stv=eff(w.st||'str');dm=(w.d||1)+ri(0,Math.floor(stv/2))-(SP[t.s].ar||0);if(a.mount){dm+=w.lance?6:2;if(MOUNTS[a.mount.s].trample)dm+=MOUNTS[a.mount.s].trample/2}}else{dm=dA.a+ri(-1,2);if(a.mount)dm+=(MOUNTS[a.mount.s].trample||0)/2+1;if(isP(t)){const ar=(G.p.eq.a?idef(G.p.eq.a).ar||0:0)+augArmor();dm-=ar}else dm-=SP[t.s].ar||0;if(a.hidden&&isP(t)){dm*=3;a.hidden=0;msg(cname(a)+' strikes from nowhere!','bad')}if(dA.tags.frenzy&&a.hp<a.mh*.5)dm+=4}
 dm=Math.max(1,Math.round(dm));if(isP(a)){const w=idef(a.eq.w);if(w.mercy||w.ench==='mercy'||t.duel){hurt(t,dm,a,'mercy');msg('You batter '+cname(t)+' ('+dm+').');applyEnch(w,t);return true}}
 if(isP(a))msg('You hit '+cname(t)+' for '+dm+'.','');else if(isP(t))msg(cname(a)+' hits you for '+dm+'.','bad');else if(visible(a.x,a.y))msg(cname(a)+' hits '+cname(t)+'.');
 if(!isP(a)){if(dA.tags.venom)poisonEnt(t,5);if(dA.tags.feverbite&&isP(t)&&chance(.15))infect(t,'marsh');if(dA.tags.lycan&&isP(t)&&chance(.08))infect(t,'lycan');if(dA.tags.paralyzetouch&&chance(.2)){if(isP(t)){msg('Your limbs lock up!','bad');RT.forceWait=2}else t.para=2}if(dA.tags.drain){a.hp=Math.min(a.mh,a.hp+2)}if(dA.tags.vampire){a.hp=Math.min(a.mh,a.hp+3);if(isP(t)&&chance(.12))infect(t,'vampire');else if(!isP(t)&&SP[t.s].tags.person&&!t.dz&&chance(.3)){t.dz='vampire';t.dzT=9999}}if(['wolf','fox','bat','dog','rat','jackal','hyena'].includes(a.s)&&isP(t)&&chance(.015))infect(t,'rabies');if(a.s==='rat'&&isP(t)&&chance(.03))infect(t,'boil');if(isP(t)&&dm>=6&&chance(.01))infect(t,'lockjaw');if(dA.tags.petrify&&isP(t)&&chance(.08)){msg('Your skin stiffens like stone!','bad');RT.forceWait=3}
  if(dA.tags.zombiebite){if(isP(t)&&chance(.2))infect(t,'zombie');else if(!isP(t)&&!SP[t.s].tags.undead&&!t.aegis&&!t.dz&&chance(.45)){t.dz='zombie';t.dzT=ri(20,40)}}
  if(a.dz==='mania'){if(isP(t)&&chance(.08))infect(t,'mania');else if(!isP(t)&&SP[t.s].tags.person&&!t.aegis&&!t.dz&&chance(.25)){t.dz='mania';t.dzT=200}}if(a.dz==='cough'&&isP(t)&&chance(.05))infect(t,'cough');if(dA.tags.carrier&&isP(t)&&chance(.06))infect(t,'cough');if(a.s==='thirsty'&&isP(t)&&chance(.1))infect(t,'mummy')}
 if(isP(a)){const w=idef(a.eq.w);applyEnch(w,t);if(w.ench==='leech')a.hp=Math.min(a.mh,a.hp+Math.ceil(dm/2));if(!w.quiet&&w.ench!=='silence')noise(a.x,a.y,6,'p')}else noise(a.x,a.y,4);hurt(t,dm,a,'blow');return true}
function applyEnch(w,t){if(isP(t)||t.dead)return;const e=w.ench;if(e==='flame'){t.burning=3;t.fireBy=1}else if(e==='frost')t.slow=6;else if(e==='venom'){t.poison=6;t.poisonBy='p'}else if(e==='thunder')shockFrom(t.x,t.y,5,G.p,t);else if(e==='dread'&&chance(.35))t.fear=6}
function hitChance(a,t){let v;if(isP(a)){const w=idef(a.eq.w);const dv=Math.floor(SP[t.s].s/20)-5;v=74+(eff(w.st||'str')-5)*4-dv*2}else{const dg=isP(t)?(eff('agi')-4)*5:0;v=70+(SP[a.s].a-4)*2-dg}if(t.sleep>0||t.stuck>0||t.para>0)v+=40;if(t.mount&&isP(a))v+=5;return clamp(v,10,98)}
function unaware(t){return t.sleep>0||(t.alert<2&&!(t.grudge&&t.grudge.p))}
function stealthPct(t,base){const hpPen=Math.min(40,t.mh*.5);let v=base+eff('sth')*8-hpPen+(t.sleep>0?30:0)+(G.p.sneak?10:0);if(isNight())v+=5;if(idef(G.p.eq.w).quiet)v+=10;if(G.wx.k==='fog')v+=5;return clamp(Math.round(v),5,97)}
function afterStealth(t,killed){const near=RT.act.filter(o=>o!==t&&!o.sleep&&(o.fac===t.fac)&&dist(o.x,o.y,t.x,t.y)<=7);const seen=near.some(o=>dist(o.x,o.y,G.p.x,G.p.y)<=6&&los(o.x,o.y,G.p.x,G.p.y)&&chance(.45-eff('sth')*.03));if(!near.length)return;if(seen){near.forEach(o=>{o.alert=2;o.lastSeen={x:G.p.x,y:G.p.y}});msg('You were seen!','warn');crime(killed?'murder':'assault',t)}else{near.forEach(o=>{o.confused=ri(5,9);o.alert=1;o.lastSeen=null});msg('No one saw you. Confusion spreads: "Who\'s there?"','good');story('A silent '+(killed?'kill':'takedown')+' threw '+near.length+' '+FAC[t.fac].n+' into panic.',2);gainXP(4)}}
function doStealthKill(t){const pct=stealthPct(t,25);if(chance(pct/100)){msg('You kill '+cname(t)+' before it can make a sound.','kill');if(t.aegis){hurt(t,1,G.p);return advance(100)}t.hp=0;die(t,G.p,'stealth');afterStealth(t,true)}else{msg('Your strike is not clean.','warn');meleeHit(G.p,t);t.alert=2;afterStealth(t,false)}advance(100)}
function doKnockout(t){const pct=stealthPct(t,40);if(chance(pct/100)){if(t.aegis)msg('The Aegis throws you back.','warn');else{t.sleep=80;t.ko=1;G.stats.knockouts++;msg(cname(t)+' goes limp. Unconscious, not dead.','good');gainXP(Math.max(2,SP[t.s].xp>>1));afterStealth(t,false)}}else{msg('Your grip slips. '+cname(t)+' whirls around!','warn');t.sleep=0;t.alert=2;(t.grudge=t.grudge||{}).p=1;crime('assault',t)}advance(100)}
function pickPct(t){return clamp(Math.round(20+eff('sth')*6+eff('spd')*2+(t.sleep>0?35:0)-(SP[t.s].tags.unique?20:0)),5,97)}
function doPickpocket(t){const pct=pickPct(t);if(chance(pct/100)){const got=[];if(t.coins){G.p.coins+=t.coins;got.push(t.coins+' coins');t.coins=0}const loot=t.inv.slice();if(loot.length){const it=loot.find(i=>i.k==='shard'||i.k==='key_gate')||pick(loot);t.inv.splice(t.inv.indexOf(it),1);if(it.k==='shard')it.cont=t.subking;giveItem(it,true);got.push(iname(it));afterGain(it)}msg(got.length?'You lift '+got.join(' and ')+' unnoticed.':'Their pockets are empty.','good');G.stats.thefts++;gainXP(3);if(got.some(s=>s.includes('Shard')))story('Picked a shard right off '+cname(t)+'.',3)}else{msg(cname(t)+' catches your hand!','bad');t.sleep=0;t.alert=2;(t.grudge=t.grudge||{}).p=1;crime('theft',t)}advance(100)}
function doSpike(t,k){const d=ITEMS[k];takeItem(k);const sp=d.spike;msg('You slip '+d.n.toLowerCase()+' into '+cname(t)+"'s drink.",'good');if(t.aegis){msg('The Aegis burns it away.','warn');advance(100);return}if(sp==='sleep'){t.sleep=t.drunk?140:70;t.ko=1;G.stats.knockouts++;if(t.drunk)story('Drugged a drunken sub-king.',2)}else if(sp==='poison'){t.poison=25;t.poisonBy='p'}else if(sp==='mania'){t.dz='mania';t.dzT=240;story('Dosed '+cname(t)+' with Red Mania.',2);G.flags.mania=G.flags.mania||G.turn}else if(sp==='zombie'){t.dz='zombie';t.dzT=40;story('Poisoned '+cname(t)+' with the Grey Walk.',3);G.flags.grey=G.flags.grey||G.turn}G.stats.thefts++;advance(100)}
function canShoot(){const w=idef(G.p.eq.w);return w.rng?w:null}
function shootPct(t){const dd=dist(G.p.x,G.p.y,t.x,t.y);return clamp(Math.round(62+(eff('agi')-5)*6-dd*2+(t.sleep>0?25:0)-(G.p.mount?6:0)),5,97)}
function firstOnLine(x0,y0,x1,y1){let dx=Math.abs(x1-x0),dy=Math.abs(y1-y0),sx=x0<x1?1:-1,sy=y0<y1?1:-1,e=dx-dy,x=x0,y=y0;while(!(x===x1&&y===y1)){const e2=2*e;if(e2>-dy){e-=dy;x+=sx}if(e2<dx){e+=dx;y+=sy}const t=at(x,y);if(t&&!isP(t))return t;const d=tdef(x,y);if(d.boom)return{barrel:1,x,y};if(d.o&&!(x===x1&&y===y1))return{wall:1,x,y}}return null}
function doShoot(x,y){const p=G.p,w=canShoot();if(!w)return;if(w.gun){if(!p.loaded&&!w.norld){msg('Reload first.','warn');return}if(w.norld&&!hasItem('shot')){msg('You are out of shot.','warn');return}if(w.norld)takeItem('shot');p.loaded=false;if((raining()&&outdoors(p.x,p.y)||p.fx.wet)&&chance(.3)){msg('Damp powder. The gun only fizzes.','warn');advance(100);return}}else if(w.usesStone){if(!hasItem('stone')){msg('You need stones for a sling.','warn');return}takeItem('stone')}else if(w.bow){if(!hasItem('arrow')){msg('You have no arrows.','warn');return}takeItem('arrow')}
 const hit=firstOnLine(p.x,p.y,x,y);RT.fxq.push({type:'shot',x:p.x,y:p.y,x2:x,y2:y});if(w.gun&&w.ench!=='silence'){noise(p.x,p.y,14,'p');if(L.world&&biomeKey(p.x,p.y)==='mountain'&&seasonIdx()===3&&chance(.35))avalanche(p.x,p.y)}else noise(p.x,p.y,3,'p');
 if(hit&&hit.barrel){msg('The shot finds the powder barrel.','warn');tset(hit.x,hit.y,'rubble');explode(hit.x,hit.y,3,p)}else if(hit&&!hit.wall){const t=hit;const pct=shootPct(t);if(unaware(t)&&SP[t.s].tags.person&&!hostile(t,p))crime('murder',t);if(chance(pct/100)){let dm=(w.d||3)+ri(0,Math.floor(eff('agi')/2))-(SP[t.s].ar||0);if(unaware(t))dm=Math.round(dm*1.5);msg('Your shot hits '+cname(t)+' for '+dm+'.','');applyEnch(w,t);if(w.ench==='leech')p.hp=Math.min(p.mh,p.hp+Math.ceil(dm/2));hurt(t,Math.max(1,dm),p,w.ench==='mercy'?'mercy':'gunshot');if(w.bow&&chance(.5))addItem(L,t.x,t.y,mk('arrow'))}else{msg('Your shot misses.','');t.alert=2;if(w.bow&&chance(.6))addItem(L,x,y,mk('arrow'))}}else{const dd=tdef(x,y);if(w.gun&&dd.f&&chance(.1))ignite(x,y,1)}advance(100)}
function doReload(){const p=G.p,w=canShoot();if(!w||!w.gun)return;if(p.loaded){msg('Already loaded.','hint');return}if(!takeItem('shot')){msg('You have no powder and shot.','warn');return}p.loaded=true;msg('You ram home a charge.','');advance(120)}
// ===== SPELLS =====
function mindResisted(t,power){const d=SP[t.s];if(t.aegis)return true;if(d.tags.mindless&&!d.tags.undead)return true;if(d.tags.construct||d.tags.ship)return true;const ch=clamp(power*9-t.mh*.4+30,8,97);return !chance(ch/100)}
function castSpell(s,c,x,y){const pl=isP(c);const pw=pl?eff('int'):5;const t=at(x,y);const name=pl?'You':cname(c);RT.fxq.push({type:'bolt',x:c.x,y:c.y,x2:x,y2:y,s});if(!pl&&(visible(c.x,c.y)||(t&&isP(t))))msg(name+' casts '+SPELLS[s].n+'!','warn');
 switch(s){
 case'firebolt':{if(t){t.burning=Math.max(t.burning||0,4);if(!isP(t))t.fireBy=pl?1:0;hurt(t,5+pw,c,'fire')}ignite(x,y,pl?1:0);if(tdef(x,y).icy)meltTile(x,y);if(tdef(x,y).water&&!t)addGas(x,y,'steam',4);const v=vesselAt(x,y);if(v){v.hp-=5;checkSink(v)}noise(x,y,6,pl?'p':null);break}
 case'frost':{if(t){hurt(t,3+(pw>>1),c,'frost');if(!isP(t))t.slow=8;t.burning=0}for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){freezeTile(x+dx,y+dy,40);delete L.fire[IX(x+dx,y+dy)]}break}
 case'shock':shockFrom(x,y,4+pw,c,t);break;
 case'heal':if(pl){c.hp=Math.min(c.mh,c.hp+8+pw*2);msg('Warmth knits your wounds.','good')}break;
 case'sleep':if(t){if(isP(t)){if(!chance((eff('int')*8+10)/100)){msg('Your eyelids slam shut.','bad');RT.forceWait=3}else msg('You shake off the sleep spell.','good')}else if(!SP[t.s].tags.undead&&!mindResisted(t,pw)){t.sleep=24;t.ko=1;if(pl)msg(cname(t)+' sinks to the ground.','good')}else if(pl)msg(cname(t)+' resists.','warn')}break;
 case'charm':if(t){if(isP(t)){if(!chance((eff('int')*8+10)/100))p_dom(5)}else if(pl){if((SP[t.s].tags.animal||t.mh<=15)&&!mindResisted(t,pw)){t.charm=70;t.alert=0;delete t.grudge;msg(cname(t)+' looks at you with sudden devotion.','good');gainXP(3)}else msg('It does not take.','warn')}else if(!mindResisted(t,3)){t.mindfac=c.fac;t.mindT=25;t.alert=0}}break;
 case'fear':if(t){if(isP(t)){if(!chance((eff('int')*7+10)/100))p_dom(3)}else if(!mindResisted(t,pw)||!SP[t.s].tags.brave){t.fear=12;if(pl)msg(cname(t)+' flees in terror.','good')}}break;
 case'brainwash':if(t){if(isP(t)){if(!chance((eff('int')*7+5)/100)){p_dom(8);msg(name+' reaches into your mind!','bad');story(name+' seized your mind.',2)}else msg('You push '+name+' out of your head.','good')}else if(pl){if(t.id===G.kingId&&!t.aegis&&!mindResisted(t,pw)){msg('The king\'s eyes go flat. He belongs to you now.','story');endGame('puppet');return}if(SP[t.s].tags.person&&!mindResisted(t,pw)){t.charm=45;t.mindOld=t.fac;t.alert=0;t.grudge={};delete t.truce;msg(cname(t)+' turns to look at its friends. It is smiling.','good');story('Brainwashed '+SP[t.s].n+' into fighting its own kin.',2);G.stats.brainwash++;gainXP(6);crime('mind-theft',t)}else msg(cname(t)+' resists.','warn')}else if(!mindResisted(t,4)&&!t.aegis){t.mindfac=c.fac;t.mindT=30;t.alert=0;t.grudge={};if(visible(x,y))msg(cname(t)+' turns on its own side.','warn')}}break;
 case'raise':raiseAt(x,y,c);break;
 case'blink':if(pl){if(tdef(x,y).p&&!at(x,y)){c.x=x;c.y=y;msg('Space folds. You are elsewhere.','good')}}else{const q=findTile(c,5,(dd,a,b)=>dd.p&&!at(a,b));if(q)moveC(c,q.x,q.y)}break;
 case'gust':{for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const nx=x+dx,ny=y+dy;if(L.gas[IX(nx,ny)])delete L.gas[IX(nx,ny)];const e=at(nx,ny);if(e&&e!==c)pushEnt(e,c.x,c.y,3,c);if(L.fire[IX(nx,ny)]&&chance(.5)){delete L.fire[IX(nx,ny)];const w=pick(DIRS);ignite(nx+w[0]*2,ny+w[1]*2,pl?1:0)}}if(pl&&G.p.aboard){G.wind={dx:Math.sign(x-c.x),dy:Math.sign(y-c.y)};msg('Your sails fill.','good')}noise(x,y,5,pl?'p':null);break}
 case'waterwalk':if(pl){c.fx.waterwalk={t:30+pw*4};msg('The water firms under your feet.','good')}break;
 case'summon':if(pl){const bk=biomeKey(c.x,c.y);const tab=(WILD[bk]||WILD.forest).filter(([s])=>SP[s].tags.predator||SP[s].tags.territorial);const sp=tab.length?wpick(tab):'wolf';const q=passableSpot(c.x,c.y,2);if(q){const z=spawn(sp,q.x,q.y,{ally:1,life:120});msg('A '+SP[sp].n.toLowerCase()+' answers your call.','good')}}break;
 }}
function p_dom(n){G.p.dom=Math.max(G.p.dom,n);msg('Your body stops obeying you.','bad')}
function pushEnt(e,fx,fy,n,src){const dx=Math.sign(e.x-fx)||0,dy=Math.sign(e.y-fy)||0;for(let i=0;i<n;i++){const nx=e.x+dx,ny=e.y+dy;const d=tdef(nx,ny);if(!inb(L,nx,ny)||at(nx,ny)||(!d.p&&!d.swim)){if(i>0)hurt(e,3,src,'impact');return}if(isP(e)){e.x=nx;e.y=ny}else{RT.occ.delete(IX(e.x,e.y));e.x=nx;e.y=ny;RT.occ.set(IX(nx,ny),e)}if(d.swim&&!isP(e)&&!SP[e.s].tags.flier&&!SP[e.s].tags.swimmer&&!SP[e.s].tags.sea){if(visible(nx,ny))msg(cname(e)+' is thrown into deep water.','good');hurt(e,e.hp+1,src,'fall');return}if(d.lava&&!isP(e)){hurt(e,e.hp+1,src,'fire');return}if(d.trap&&!isP(e))trap(e,nx,ny)}}
function shockFrom(x,y,dm,c,t){const seen=new Set(),hit=[];seen.add(IX(x,y));const q=[[x,y]];let h=0;while(h<q.length&&seen.size<60){const[a,b]=q[h++];const e=at(a,b);if(e&&e!==c&&!hit.includes(e))hit.push(e);for(const[dx,dy]of DIRS){const nx=a+dx,ny=b+dy;if(!inb(L,nx,ny))continue;const k=IX(nx,ny);if(seen.has(k))continue;const dd=tdef(nx,ny);const oc=at(nx,ny);if(dd.water||dd.swim||(oc&&(oc.wet>0||(isP(oc)&&oc.fx.wet)))||tdef(a,b).water&&oc){seen.add(k);q.push([nx,ny])}}}if(t&&!hit.includes(t))hit.push(t);RT.fxq.push({type:'burst',x,y,e:'shock'});hit.forEach(e=>{const wet=isP(e)?!!e.fx.wet:e.wet>0;hurt(e,wet?dm*2:dm,c,'lightning');if(!isP(e))e.stun=1;if(visible(e.x,e.y))msg('Lightning arcs through '+(isP(e)?'you':cname(e))+'!',isP(e)?'bad':'good')});if(hit.length>2&&isP(c))story('One bolt of lightning ran through '+hit.length+' creatures in the water.',2);noise(x,y,8,isP(c)?'p':null)}
function raiseAt(x,y,c){const k=IX(x,y),its=L.items[k];if(!its)return false;const cp=its.find(i=>i.k==='corpse');if(!cp)return false;its.splice(its.indexOf(cp),1);if(!its.length)delete L.items[k];const sp=SP[cp.sp]||SP.villager;const z=spawn('undeadthrall',x,y,{life:isP(c)?300:0,fac:isP(c)?'player':c.fac,ally:isP(c)?1:0,mh:Math.max(8,sp.hp*.7|0),hp:Math.max(8,sp.hp*.7|0),wild:1});z.origin=cp.sp;if(visible(x,y))msg(sp.n+' corpse lurches upright.',isP(c)?'good':'warn');if(isP(c)){G.stats.raised++;gainXP(4);story('Raised a '+sp.n+' from the dead.',2);crime('necromancy',{fac:'free'})}return true}
function spellCost(e){let c=0;(e.fx||[]).forEach(f=>{const d=EFFECTS[f.e];c+=d.c*f.mag*(1+f.area*.8)*(1+f.dur/15)});return Math.max(1,Math.round(c/(1+eff('int')*.07)))}
function customCost(sp){return spellCost(sp)}
function targetsIn(x,y,r){const o=[];for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){if(Math.hypot(dx,dy)>r+.4)continue;const e=at(x+dx,y+dy);if(e)o.push(e)}return o}
function castCustom(sp,x,y){const p=G.p;const cost=customCost(sp);if(p.mp<cost){const blood=cost-p.mp;if(p.hp<=blood){msg('Casting this now would kill you.','bad');return false}p.mp=0;p.hp-=blood;msg('You pay the difference in blood: '+blood+' health.','bad')}else p.mp-=cost;RT.fxq.push({type:'bolt',x:p.x,y:p.y,x2:x,y2:y,s:'custom'});msg('You cast '+sp.name+'.','good');sp.fx.forEach(f=>applyEffect(f.e,f.mag,f.area,f.dur,p,x,y));noise(x,y,6,'p');advance(100);return true}
function applyEffect(e,mag,area,dur,c,x,y){const p=G.p,def=EFFECTS[e];const tg=def.t==='self'?[p]:targetsIn(x,y,area);const each=fn=>tg.forEach(t=>{if(t!==c||def.t==='self')fn(t)});const tiles=fn=>{for(let dy=-area;dy<=area;dy++)for(let dx=-area;dx<=area;dx++){if(Math.hypot(dx,dy)>area+.4)continue;fn(x+dx,y+dy)}};
 switch(e){case'fire':each(t=>{hurt(t,mag,c,'fire');if(t.hp>0){t.burning=Math.max(t.burning||0,dur+1);if(!isP(t))t.fireBy=1}});tiles((a,b)=>ignite(a,b,1));break;
 case'frost':each(t=>{hurt(t,mag,c,'frost');if(!isP(t))t.slow=dur+3});tiles((a,b)=>freezeTile(a,b,dur*3+30));break;case'shock':shockFrom(x,y,mag,c,at(x,y));each(t=>{if(!isP(t))t.stun=Math.max(t.stun||0,Math.min(3,dur))});break;
 case'poison':each(t=>{if(!isP(t)){t.poison=Math.max(t.poison||0,dur+mag);t.poisonBy='p'}else poisonEnt(t,dur)});break;case'drain':{let g=0;each(t=>{hurt(t,mag,c,'drain');g+=mag});p.hp=Math.min(p.mh,p.hp+g);break}
 case'heal':p.hp=Math.min(p.mh,p.hp+mag);if(area>0)RT.act.forEach(o=>{if(dist(o.x,o.y,p.x,p.y)<=area&&(o.ally||o.charm>0))o.hp=Math.min(o.mh,o.hp+mag)});break;case'restore':p.hunger=clamp(p.hunger+mag,0,100);p.thirst=clamp(p.thirst+mag,0,100);if(mag>=25){p.dz=[];msg('Every sickness leaves your body.','good')}break;
 case'haste':p.fx.haste={v:Math.ceil(mag/6),t:dur+1};msg('Everything else slows down.','good');break;case'might':p.fx.might={v:Math.ceil(mag/6),t:dur+1};recalc();msg('Strength floods your arms.','good');break;case'invis':p.fx.invis={t:dur+1};msg('You fade from sight.','good');break;case'aegis':p.fx.absorb={v:mag*2,t:dur+1};msg('A ward shimmers around you.','good');break;case'waterwalk':p.fx.waterwalk={t:dur*3+10};msg('The water firms under you.','good');break;
 case'timestop':p.fx.tstop={t:Math.max(1,dur)};msg('The world holds its breath.','story');story('Stopped time.',3);break;
 case'sleep':each(t=>{if(isP(t))return;if(!t.aegis&&!SP[t.s].tags.undead&&!SP[t.s].tags.mindless&&(mag*3>=t.mh*.5||!mindResisted(t,mag/3))){t.sleep=dur*2+8;t.ko=1;G.stats.knockouts++;msg(cname(t)+' collapses asleep.','good')}});break;
 case'calm':each(t=>{if(isP(t)||t.aegis)return;if(mag*3>=t.mh*.5||!mindResisted(t,mag/3)){t.truce=G.turn+dur*3+15;t.alert=0;delete t.grudge;t.confused=0;msg(cname(t)+' lowers its guard.','good')}});break;case'fear':each(t=>{if(!isP(t)&&!t.aegis)t.fear=dur+4});break;
 case'charm':each(t=>{if(isP(t)||t.aegis)return;if(t.id===G.kingId){msg('The king\'s eyes go flat.','story');endGame('puppet');return}if(mag*3>=t.mh*.6||!mindResisted(t,mag/3)){t.charm=dur*3+15;t.alert=0;t.grudge={};if(SP[t.s].tags.person)t.mindOld=t.fac;msg(cname(t)+' now serves you.','good');G.stats.brainwash++}});break;
 case'paralyze':each(t=>{if(!isP(t)&&!t.aegis)t.para=dur+1});break;case'confuse':each(t=>{if(!isP(t)&&!t.aegis)t.confused=dur+3});break;
 case'quake':noise(x,y,20,'p');if(L.world&&biomeKey(x,y)==='mountain'&&seasonIdx()===3)avalanche(x,y);tiles((a,b)=>{const d=tdef(a,b);if((d.wall||d.door||d.k==='rock'||d.gate||d.k==='cavewall'||d.k==='redrock')&&!d.seal){if(chance(mag/40+.25)){tset(a,b,'rubble');if(d.gate)msg('The gate buckles and falls.','warn')}}else if(d.chop){if(chance(.5))tset(a,b,'stump')}else if(d.p&&chance(.2)&&!d.water)tset(a,b,'pit');const o=at(a,b);if(o)hurt(o,Math.ceil(mag/3),c,'quake')});break;
 case'inferno':tiles((a,b)=>{if(!ignite(a,b,1)&&tdef(a,b).p&&!tdef(a,b).water)L.fire[IX(a,b)]={t:dur+3,o:1}});story('Set the land ablaze with a word.',2);break;case'deepfreeze':tiles((a,b)=>{freezeTile(a,b,dur*3+60);delete L.fire[IX(a,b)];const o=at(a,b);if(o&&!isP(o)){o.para=Math.min(6,dur);o.burning=0}});break;
 case'rain':G.wx={k:'storm',t:dur*4+25};msg('Clouds pile up from nowhere.','wx');break;case'growth':tiles((a,b)=>{const d=tdef(a,b),k=IX(a,b);if(L.crops[k])L.crops[k].a=200;else if(['grass','ash','stump','sand','mud','scree','savgrass','steppegrass','moss'].includes(d.k)&&!at(a,b)&&chance(.55))tset(a,b,chance(.4)?'tree':'vines')});msg('The ground heaves with green.','good');break;
 case'teleport':if(tdef(x,y).p&&!at(x,y)){p.x=x;p.y=y;msg('You step through the air.','good')}break;case'raiseall':tiles((a,b)=>raiseAt(a,b,p));break;
 case'tidal':tiles((a,b)=>{const d=tdef(a,b);if(d.p&&!d.indoor&&!d.wall&&chance(.6))tset(a,b,'flood');const o=at(a,b);if(o&&!isP(o)){pushEnt(o,x,y,2,c);hurt(o,Math.ceil(mag/2),c,'wave');o.wet=10;delete L.fire[IX(a,b)]}});msg('A wall of water crashes down.','good');break;}}
function playerCast(s,x,y){const p=G.p;const d=SPELLS[s];if(p.mp<d.mp){msg('Not enough mana.','warn');return false}if(!d.self&&dist(p.x,p.y,x,y)>d.rng){msg('Out of range.','warn');return false}if(!d.self&&!los(p.x,p.y,x,y)&&s!=='blink'){msg('No line of sight.','warn');return false}if(s==='raise'&&!(L.items[IX(x,y)]||[]).some(i=>i.k==='corpse')){msg('There is no corpse there.','warn');return false}p.mp-=d.mp;const t=at(x,y);if(t&&!isP(t)&&SP[t.s].tags.person&&!hostile(t,p)&&['firebolt','shock','frost'].includes(s))crime('assault',t);castSpell(s,p,x,y);if(p.fx.invis)delete p.fx.invis;advance(100);return true}
function doThrow(it,x,y){const p=G.p,d=idef(it);if(dist(p.x,p.y,x,y)>7){msg('Too far to throw.','warn');return}const q=mk(it.k,1);if(it.sp)q.sp=it.sp;if(it.x)q.x=it.x;if((it.q||1)>1)it.q--;else{if(p.eq.w===it)p.eq.w=null;if(p.eq.a===it)p.eq.a=null;p.inv.splice(p.inv.indexOf(it),1)}RT.fxq.push({type:'shot',x:p.x,y:p.y,x2:x,y2:y});if(d.effect){msg('You throw '+d.n.toLowerCase()+'.','');const t=at(x,y);if(d.effect==='noise'&&t&&!isP(t)){hurt(t,2,p,'stone');msg('The stone cracks against '+cname(t)+'.')}throwEffect(d.effect,x,y,p);if(d.effect!=='noise'&&t&&!isP(t)&&SP[t.s].tags.person&&!hostile(t,p))crime('assault',t);if(d.effect==='noise')addItem(L,x,y,mk('stone'))}else{addItem(L,x,y,q);msg(d.n+' lands nearby.','');noise(x,y,4)}advance(100)}
// ===== ITEMS =====
function useItem(it){const p=G.p,d=idef(it);if(d.k==='wpn'||d.k==='arm'){if(d.req){for(const s in d.req)if(p.st[s]<d.req[s]){msg('You need '+STATN[s]+' '+d.req[s]+' for that.','warn');return}}if(d.k==='wpn'){p.eq.w=p.eq.w===it?null:it;msg((p.eq.w?'You wield ':'You put away ')+d.n+'.')}else{p.eq.a=p.eq.a===it?null:it;msg((p.eq.a?'You wear ':'You take off ')+d.n+'.');if(p.eq.a&&d.disg)msg('Dressed as the '+FAC[d.disg].n+'. They won\'t look twice unless you act strangely.','hint')}recalc();advance(60);return}
 if(d.k==='food'||d.k==='drink'||d.k==='med'&&!d.spike){if(d.hun)p.hunger=clamp(p.hunger+d.hun,0,100);if(d.thi)p.thirst=clamp(p.thirst+d.thi,0,100);if(d.hp)p.hp=Math.min(p.mh,p.hp+d.hp);if(d.mp)p.mp=Math.min(p.mmp,p.mp+d.mp);if(d.warm)p.fx.warm={t:d.warm};if(d.cool)p.fx.cool={t:d.cool};if(d.breath)p.fx.gills={t:120};if(d.boost){p.fx.boost={k:d.boost,v:2,t:80};recalc();msg('Your '+STATN[d.boost]+' rises.','good')}if(d.cure){const n=cureWith(['tonic']);delete p.fx.poison;msg(n?'The sickness loosens and leaves you.':(p.dz.length?'It helps a little, but this sickness needs a different remedy.':'It tastes bitter and clean.'),n?'good':'hint')}if(isVamp()&&(d.k==='food')){msg('It turns to ash in your mouth. Only blood feeds you now.','bad');takeItem(it.k);advance(70);return}if(d.raw&&chance(p.herb?.08:d.fish?.15:.3))infect(p,'rot');if(d.dirty&&chance(.35))infect(p,chance(.5)?'dysentery':'rot');if(d.risky&&chance(p.herb?.05:.2)){p.fx.poison={t:6};msg('That mushroom was a mistake.','bad')}if(d.fish&&!d.raw||it.k==='berries'||it.k==='coconut')p.dz=p.dz.filter(z=>z.k!=='scurvy'||chance(.5));msg('You '+(d.k==='drink'?'drink':d.k==='med'?'use':'eat')+' '+d.n.toLowerCase()+'.');const emp=d.empty;takeItem(it.k);if(emp)giveItem(mk(emp),true);advance(70);return}
 if(d.k==='scroll'){const s=it.sp;const sd=SPELLS[s];if(!sd){msg('The words are too faded.','warn');return}if(eff('int')<sd.int){msg('You need Intelligence '+sd.int+' to learn this.','warn');return}if(p.spells.includes(s)){msg('You already know this. You grind it into dust.','hint');giveItem(mk('dust'),true)}else{p.spells.push(s);msg('You learn '+sd.n+'.','good');gainXP(10)}p.inv.splice(p.inv.indexOf(it),1);advance(100);return}
 if(d.lore){learnLore(d.lore);return}if(it.k==='potion'||it.k==='brew'){drinkPotion(it);return}if(REAGENTS.includes(it.k)&&d.k==='herb'){tasteReagent(it);return}if(it.k==='suncell'){if(!augOn()){msg('You have no augments to charge.','hint');return}p.charge=Math.min(100,(p.charge||0)+40);takeItem('suncell');msg('The cell flares and your augments drink it in.','good');advance(60);return}if(it.k==='augkit'){msg('An augment kit. An artificer could install this for you.','hint');return}if(it.k==='letter'){msg('A letter, sealed. Deliver it.','hint');return}
 if(it.k==='treasuremap'){if(!it.tx){const c=pick(G.conts.filter(q=>q.real));let tx,ty;for(let i=0;i<60;i++){tx=c.cx0+ri(30,CELL-30);ty=c.cy0+ri(30,CELL-30);const tb=terrainAt(tx,ty);if(TDEF[TN[tb&255]].p&&!TDEF[TN[tb&255]].water)break}it.tx=tx;it.ty=ty;it.cname=c.name}msg('The map shows an X on '+it.cname+', near '+compass(it.tx-p.x,it.ty-p.y)+'. Dig there with a shovel.','hint');G.marks.push({x:it.tx,y:it.ty,t:'X marks the spot'});return}
 if(it.k==='torch'){if(p.torch>0){msg('Your torch is already lit.','hint');return}takeItem('torch');p.torch=90;msg('You light a torch.','good');advance(40);return}
 if(it.k==='spyglass'){p.fx.spy={t:1};computeFOV();msg('You sweep the horizon with the spyglass.','good');const near=G.bands.filter(b=>dist(b.x,b.y,p.x,p.y)<60);near.slice(0,4).forEach(b=>msg('You spot '+bandDesc(b)+' to the '+compass(b.x-p.x,b.y-p.y)+'.','hint'));advance(60);return}
 if(it.k==='chalk'){if(tdef(p.x,p.y).p&&!tdef(p.x,p.y).water){takeItem('chalk');tset(p.x,p.y,'sigil');msg('You draw a warding sigil. Beasts and the dead will not strike you while you stand on it.','good');advance(100)}return}
 if(d.k==='herb'&&it.k==='bloodmoss'&&p.herb){p.hp=Math.min(p.mh,p.hp+6);takeItem(it.k);msg('You chew the moss.','good');advance(70);return}
 msg('You cannot use that directly. Try throwing it, crafting with it, or giving it to someone.','hint')}
function bandDesc(b){const m=b.members.filter(x=>!x.dead);const s=SP[m[0].s];if(b.kind==='seamonster'||b.kind==='monster'||b.kind==='herd')return(m.length>1?m.length+' ':'a ')+s.n.toLowerCase()+(m.length>1?'s':'');if(b.ship)return(b.fac==='pirate'?'a pirate ':'a ')+s.n.toLowerCase();return(b.fac==='horde'?'a Horde ':b.fac==='plague'?'a plague swarm of ':b.nation!=null?'a '+G.nations[b.nation].short+' ':'a ')+(b.kind==='caravan'?'caravan':b.kind==='swarm'?m.length+' walkers':'company of '+m.length)}
function dropItem(it){const p=G.p;const q=Object.assign({},it);if(p.eq.w===it)p.eq.w=null;if(p.eq.a===it)p.eq.a=null;p.inv.splice(p.inv.indexOf(it),1);addItem(L,p.x,p.y,q);msg('You drop '+iname(q)+'.');if(idef(q).meat&&!p.sneak)msg('The smell of meat drifts on the wind.','hint');advance(40)}
function foodList(){return G.p.inv.filter(i=>idef(i).k==='food'||idef(i).k==='bait')}
function pickupAll(x,y){const k=IX(x,y),its=L.items[k];if(!its)return;for(const it of its.slice()){if(it.k==='corpse')continue;if(it.k==='relic'&&nearSite(x,y,2)&&nearSite(x,y,2).type==='shrine'&&RT.act.some(c=>c.role==='priest'&&visible(c.x,c.y)))crime('theft',{fac:'free'});if(giveItem(it))its.splice(its.indexOf(it),1)}if(!its.length)delete L.items[k];advance(50)}
function butcher(x,y){const k=IX(x,y),its=L.items[k];if(!its)return;const c=its.find(i=>i.k==='corpse');if(!c)return;its.splice(its.indexOf(c),1);if(!its.length)delete L.items[k];const sp=SP[c.sp];if(sp&&!sp.tags.person){Object.entries(sp.loot||{}).forEach(([m,q])=>addItem(L,x,y,mk(m,ri(1,q))));addItem(L,x,y,mk('rawmeat',1))}addItem(L,x,y,mk('bone',1));if(c.dz==='zombie'&&chance(.6)){addItem(L,x,y,mk('bile',1));msg('You drain a vial of grey bile. Handle with care.','warn')}if(c.dz&&chance(.3))infect(G.p,c.dz==='cough'?'cough':'rot');msg('You butcher the corpse.','');if(sp&&sp.tags.person){crime('desecration',{fac:'free'});msg('It is grim work.','warn')}advance(200)}
function sleepRest(bed){const p=G.p;let n=bed?40:15;msg(bed?'You lie down to sleep.':'You rest.','hint');for(let i=0;i<n&&!G.over;i++){const danger=RT.act.some(c=>hostile(c,p)&&dist(c.x,c.y,p.x,p.y)<=7&&c.sleep<=0&&c.alert>=1&&visible(c.x,c.y));if(danger&&i>0){msg('Something wakes you!','bad');break}advance(100);if(RT.hit){RT.hit=0;msg('You wake up hurt!','bad');break}if(i%3===0)p.hp=Math.min(p.mh,p.hp+(bed?2:1));p.mp=Math.min(p.mmp,p.mp+(bed?1:0))}if(bed)msg('You wake.','')}
// ===== CRAFT / FORGE / SPELLMAKING =====
function craftAvail(r){if(r.near==='cook'&&!nearHeatT())return false;if(r.near==='forge'&&!nearForge())return false;return Object.entries(r.need).every(([k,q])=>count(k)>=q)}
function nearHeatT(){const p=G.p;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(tdef(p.x+dx,p.y+dy).cook||L.fire[IX(p.x+dx,p.y+dy)])return true}return false}
function nearForge(){const p=G.p;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(tdef(p.x+dx,p.y+dy).forge)return true;return false}
function nearSpellforge(){const p=G.p;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(tdef(p.x+dx,p.y+dy).arcane)return true;return false}
function doCraft(r){if(!craftAvail(r))return;Object.entries(r.need).forEach(([k,q])=>takeItem(k,q));giveItem(mk(r.out,r.q||1),true);msg('You make '+iname(mk(r.out,r.q||1))+'.','good');G.stats.crafted++;gainXP(1);advance(r.near?150:100)}
function forgeCost(b,m,e){const B=FBASE[b],M=FMAT[m],E=FENCH[e];return{mat:M.it,matq:Math.max(1,B.cost),wood:B.kind==='wpn'?1:0,dust:E.dust}}
function canForge(b,m,e){const c=forgeCost(b,m,e);return count(c.mat)>=c.matq&&count('wood')>=c.wood&&count('dust')>=c.dust}
function doForge(b,m,e){if(!nearForge()){msg('Stand beside a forge.','warn');return}if(!canForge(b,m,e)){msg('You lack the materials.','warn');return}const B=FBASE[b],M=FMAT[m],E=FENCH[e],c=forgeCost(b,m,e);takeItem(c.mat,c.matq);if(c.wood)takeItem('wood',c.wood);if(c.dust)takeItem('dust',c.dust);const skill=eff('str')+(G.p.forge||0)*2;const qual=Math.min(3,Math.floor(skill/5)+(chance(.3)?1:0));const qn=['Crude ','','Fine ','Masterwork '][qual];const x={k:B.kind,st:B.st,req:B.req?Object.assign({},B.req):undefined,v:Math.round((30+B.cost*10)*M.mult),noisy:B.noisy,quiet:B.quiet,mercy:B.mercy,manaP:B.manaP?Math.round(B.manaP*M.mult):undefined,warm:B.warm,chop:B.chop,gun:B.gun,norld:B.norld,rng:B.rng,bow:B.bow,lance:B.lance};if(M.light&&x.req)Object.keys(x.req).forEach(k=>x.req[k]=Math.max(1,x.req[k]-1));if(B.kind==='wpn')x.d=Math.round(B.d*M.mult)+qual-1;else x.ar=Math.round(B.ar*M.mult)+Math.max(0,qual-1);if(e!=='none'){x.ench=e;if(e==='mercy')x.mercy=1;if(e==='silence')x.quiet=1}x.n=qn+M.n+' '+B.n+(e!=='none'?' of '+E.n:'');Object.keys(x).forEach(k=>x[k]===undefined&&delete x[k]);const it={k:'forged',q:1,x};G.p.inv.push(it);msg('You forge '+x.n+'.','good');story('Forged '+x.n+'.',1);G.stats.crafted++;gainXP(6);noise(G.p.x,G.p.y,6,'p');advance(300);return it}
function makeSpell(name,fx){const p=G.p;const sp={id:'c'+(++G.cid),name:name||'Unnamed Working',fx};const c=spellCost(sp);const dust=Math.max(1,Math.ceil(c/18));if(!nearSpellforge()){msg('You need a spellforge.','warn');return null}if(count('dust')<dust){msg('This working needs '+dust+' arcane dust.','warn');return null}if(p.st.int+p.lvl<Math.min(12,1+Math.ceil(c/12))){msg('Beyond your skill. Lower magnitude, area, or duration.','warn');return null}takeItem('dust',dust);p.custom.push(sp);msg('You inscribe '+sp.name+'. It costs '+c+' mana.','good');story('Invented the spell '+sp.name+'.',2);G.stats.spellsMade++;gainXP(12);advance(300);return sp}
// ===== WORLD VERBS =====
function digTile(x,y){const d=tdef(x,y);const w=idef(G.p.eq.w);if(!(w.minep||hasItem('pick'))){msg('You need a pickaxe.','warn');return}noise(x,y,8,'p');if(d.ore===2)addItem(L,G.p.x,G.p.y,mk('starore',ri(1,2)));else if(d.ore)addItem(L,G.p.x,G.p.y,mk('ironore',ri(1,3)));else if(d.crys)addItem(L,G.p.x,G.p.y,mk('crystalshard',ri(1,2)));else if(d.k==='obsidian')addItem(L,G.p.x,G.p.y,mk('obsid',ri(1,2)));else addItem(L,G.p.x,G.p.y,mk('stone',ri(1,3)));tset(x,y,L.dark?'cavefloor':'rubble');msg('The rock comes apart.','');advance(300)}
function digTreasure(){const p=G.p;const m=p.inv.find(i=>i.k==='treasuremap'&&i.tx!=null&&dist(i.tx,i.ty,p.x,p.y)<=2);if(!hasItem('shovel')){msg('You need a shovel.','warn');return}if(m){p.inv.splice(p.inv.indexOf(m),1);G.marks=G.marks.filter(q=>q.x!==m.tx||q.y!==m.ty);const loot=[mk('coins',ri(80,200)),mk(pick(['stariron','pearl','ring','scale','dust']),ri(2,4)),mk(pick(['scroll','breathpot','spyglass']))];loot[2].sp=pick(Object.keys(SPELLS));loot.forEach(i=>giveItem(i));msg('Your shovel strikes a chest!','good');story('Dug up buried treasure.',2);gainXP(20)}else{msg('You dig a hole. Nothing.','');tset(p.x,p.y,'pit')}advance(250)}
function chopTile(x,y){const d=tdef(x,y);noise(x,y,8,'p');addItem(L,G.p.x,G.p.y,mk(d.k==='bamboo'?'bamboo':'wood',ri(2,3)));if(d.k==='palm'&&chance(.4))addItem(L,G.p.x,G.p.y,mk('coconut'));tset(x,y,d.k==='shroom'?'mud':'stump');msg('It comes down.','');if(d.hive)angerBees(x,y);advance(250)}
function angerBees(x,y){for(let i=0;i<3;i++){const c=spawn('bees',clamp(x+ri(-1,1),1,L.w-2),clamp(y+ri(-1,1),1,L.h-2),{grudge:{p:1},alert:2,wild:1})}msg('The hive erupts!','bad')}
function forageTile(x,y){const d=tdef(x,y);const bk=biomeKey(x,y),se=seasonIdx();if(d.k==='bush'){giveItem(mk('berries',ri(2,se===2?5:3)));if(chance(.15))giveItem(mk('seed'+pick(['wheat','turnip','gourd','rice']),1));tset(x,y,'bushbare')}else if(d.k==='mushrooms'){if(chance(.25))giveItem(mk('madcap'));else giveItem(mk('mushroom',ri(1,3)));tset(x,y,L.dark?'cavefloor':'moss')}else if(d.k==='herb'){const pool={jungle:['bloodmoss','dreamroot','ashcap','madcap'],bamboo:['dreamroot','sunleaf'],mangrove:['bloodmoss','ashcap'],swamp:['bloodmoss','ashcap','madcap'],desert:['sunleaf','ashcap'],badlands:['sunleaf','emberroot'],volcanic:['emberroot'],tundra:['frostlily','sunleaf'],taiga:['frostlily','bloodmoss'],glacier:['frostlily'],mountain:['sunleaf','bloodmoss','frostlily'],highland:['dreamroot','sunleaf']}[bk]||['bloodmoss','sunleaf','dreamroot'];giveItem(mk(pick(pool),G.p.herb?2:1));tset(x,y,'grass')}else if(d.k==='cactus'){hurt(G.p,1,null,'cactus');giveItem(mk('cactusfruit',ri(1,2)));tset(x,y,'sand')}else if(d.k==='salt'){giveItem(mk('salt',ri(1,3)))}else if(d.k==='shard'){giveItem(mk('crystalshard',1));tset(x,y,'salt')}advance(120)}
function harvestCrop(x,y){const k=IX(x,y),c=L.crops[k];if(!c)return;const def=CROPS[c.c];if(c.a<def.grow){msg('Not ripe yet.','hint');return}if(!c.o&&nearSite(x,y,4)&&RT.act.some(o=>SP[o.s].tags.person&&visible(o.x,o.y)&&!hostile(o,G.p)))crime('theft',{fac:'free',nation:nearSite(x,y,4).nation});giveItem(mk(def.item,def.q+(seasonIdx()===2?1:0)));if(chance(.6))giveItem(mk('seed'+c.c),true);delete L.crops[k];gainXP(2);advance(120)}
function plant(x,y,it){const k=IX(x,y);if(seasonIdx()===3){msg('The ground is frozen. Wait for spring.','warn');return}takeItem(it.k);L.crops[k]={c:idef(it).crop,a:0,o:1};msg('You plant '+CROPS[idef(it).crop].n+'.','good');advance(100)}
function waterCrop(x,y){const k=IX(x,y),c=L.crops[k];if(c&&takeItem('water')){c.w=G.turn+60;giveItem(mk('flask'),true);msg('You water the crop.','');advance(100)}}
function douse(x,y){if(!takeItem('water'))return;giveItem(mk('flask'),true);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)delete L.fire[IX(x+dx,y+dy)];addGas(x,y,'steam',3);const e=at(x,y);if(e&&!isP(e)){e.burning=0;e.wet=8}msg('You douse the flames.','good');advance(90)}
function lockPct(){return clamp(25+eff('sth')*5+eff('agi')*3,10,95)}
function lockpickTile(x,y){const d=tdef(x,y);if(!hasItem('lockpick')){msg('You have no lockpicks.','warn');return}if(chance(lockPct()/100)){tset(x,y,d.gate?'gateopen':'dooropen');msg('The lock clicks open.','good');gainXP(4);const cap=RT.act.find(c=>c.captive&&dist(c.x,c.y,x,y)<=3);if(cap)msg(cname(cap)+' stares at you, hardly daring to hope.','hint')}else{msg('The pick snaps in the lock.','warn');takeItem('lockpick');noise(x,y,6,'p')}advance(150)}
function buildAt(k,x,y){const B=BUILD[k];if(dist(G.p.x,G.p.y,x,y)>1&&k!=='soil'){msg('Stand next to the spot.','warn');return}const d=tdef(x,y);if(at(x,y)&&!isP(at(x,y))){msg('Something is standing there.','warn');return}if(B.vessel){if(!(d.water||d.swim)||d.icy){msg('Boats go on open water.','warn');return}if(B.pier&&!DIRS.some(([a,b])=>tdef(x+a,y+b).pier)){msg('A longship must be built beside a pier.','warn');return}if(vesselAt(x,y)){msg('Something is already moored there.','warn');return}}else if(k==='bridge'){if(!d.water&&!d.swim){msg('Bridges go on water.','warn');return}}else if(!(d.p&&!d.water&&!d.link&&!d.sacred&&d.k!=='throne'&&d.k!=='pier')){msg('You cannot build there.','warn');return}if(B.tool&&!hasItem(B.tool)){msg('You need a '+ITEMS[B.tool].n.toLowerCase()+'.','warn');return}for(const[m,q]of Object.entries(B.need))if(count(m)<q){msg('You need '+q+' '+ITEMS[m].n.toLowerCase()+'.','warn');return}if(nearSite(x,y,0)&&!B.vessel&&!['soil','campfire'].includes(k)){const s=nearSite(x,y,0);if(s.fac!=='horde'&&RT.act.some(c=>c.site===s.id&&visible(c.x,c.y))){msg('Locals object to you building in their town.','warn');return}}Object.entries(B.need).forEach(([m,q])=>takeItem(m,q));if(B.vessel){const v=newVessel(B.vessel,x,y,'p');msg('You build a '+B.vessel+'. Walk onto it to board.','good');story('Built a '+B.vessel+'.',2);gainXP(B.vessel==='longship'?25:5);advance(B.vessel==='longship'?600:300);return}tset(x,y,k);if(TDEF[k].store)L.stores[IX(x,y)]=[];msg('You build '+B.n.toLowerCase()+'.','good');gainXP(1);noise(x,y,5,'p');advance(150)}
function takeStore(x,y,it){const k=IX(x,y),st=L.stores[k];st.splice(st.indexOf(it),1);giveItem(it);advance(50)}
function putStore(x,y,it){const k=IX(x,y);const p=G.p;p.inv.splice(p.inv.indexOf(it),1);if(p.eq.w===it)p.eq.w=null;if(p.eq.a===it)p.eq.a=null;(L.stores[k]=L.stores[k]||[]).push(it);msg('Stored.','');advance(40)}
function gatherSmoke(x,y){const near=(L.gas[IX(x,y)]||{}).k==='smoke'||DIRS.some(([a,b])=>(L.gas[IX(x+a,y+b)]||{}).k==='smoke');if(near||seasonIdx()===3){giveItem(mk('honey',ri(1,3)));giveItem(mk('wax',1));msg(seasonIdx()===3?'The cold has the bees torpid. You take the comb.':'The smoke keeps the bees docile. You take the comb.','good');tset(x,y,'tree')}else{angerBees(x,y);giveItem(mk('honey',1))}advance(150)}
function drinkTile(x,y){const d=tdef(x,y);const p=G.p;const bk=biomeKey(x,y);if(d.ocean){p.thirst=clamp(p.thirst-10,0,100);msg('Salt water. It makes you thirstier.','bad');advance(50);return}p.thirst=clamp(p.thirst+40,0,100);msg('You drink deep.','good');if((d.k==='bog'||['jungle','swamp','mangrove'].includes(bk)&&d.water)&&chance(.2))infect(p,'marsh');else if(d.water&&!['oasis','spring'].includes(d.k)&&!d.waterSrc&&chance(.05))infect(p,'rot');if(d.fountain&&chance(.25))fountainEffect();advance(70)}
function fountainEffect(){const p=G.p;const r=R();if(r<.3){p.hp=p.mh;msg('The water is cold and sweet. Your wounds close.','good')}else if(r<.5){p.mp=p.mmp;msg('Your mind clears.','good')}else if(r<.6){giveItem(mk('coins',ri(5,30)));msg('There are coins at the bottom.','good')}else if(r<.7){const sp=passableSpot(p.x,p.y,2);if(sp){spawn('wisp',sp.x,sp.y,{wild:1,alert:2});msg('Something rises from the water!','bad')}}else if(r<.75&&!G.flags.wished){G.flags.wished=1;giveItem(mk('scale',2));msg('A voice in the water grants you a small wish. Two dragon scales glint in your hand.','story');story('Was granted a wish by a fountain.',3)}else msg('Just water.','')}
function fillFlask(x,y){const n=count('flask');if(!n)return;const d=tdef(x,y);if(d.ocean){msg('Seawater would only make you thirstier.','warn');return}takeItem('flask',n);giveItem(mk(['jungle','swamp','mangrove'].includes(biomeKey(x,y))&&d.water?'dirtywater':'water',n),true);msg('You fill '+n+' flask'+(n>1?'s':'')+'.','good');advance(70)}
function burnGranary(x,y){ignite(x,y,1);G.moraleH=Math.max(0,G.moraleH-12);msg('The Horde\'s grain goes up. Morale will crack.','story');story('Burned a Horde granary.',2);const s=nearSite(x,y,2);if(s&&s.subking!==undefined&&G.subkings[s.subking].trait==='starving'){G.subkings[s.subking].desperate=1}advance(100)}
function pray(){const p=G.p;if(G.turn-(p.prayT||-9999)<DAY*2){msg('The silence feels impatient. Too soon.','warn');p.prayT=G.turn-DAY;if(chance(.3)){hurt(p,4,null,'divine displeasure');msg('Something slaps you down.','bad')}advance(100);return}p.prayT=G.turn;const lowHP=p.hp<p.mh*.35;if(lowHP||p.dz.length||p.hunger<15){p.hp=p.mh;p.dz=[];p.hunger=Math.max(p.hunger,60);msg('Warm light falls over you. You are restored.','good');story('Prayed and was answered.',2)}else if(G.p.favor>=3){G.p.favor-=3;giveItem(Object.assign(mk('scroll'),{sp:pick(Object.keys(SPELLS))}));msg('A scroll appears on the altar.','good')}else msg('You feel watched, kindly.','');advance(100)}
function sacrifice(x,y){const its=L.items[IX(x,y)]||[];const c=its.find(i=>i.k==='corpse'&&G.turn-i.age<60);if(!c){msg('Only a fresh corpse will do.','warn');return}its.splice(its.indexOf(c),1);const sp=SP[c.sp];if(sp&&sp.tags.person&&sp.f!=='horde'){msg('The altar darkens. That was a mistake.','bad');G.p.favor=(G.p.favor||0)-3;crime('desecration',{fac:'free'})}else{G.p.favor=(G.p.favor||0)+Math.ceil((sp?sp.xp:1)/5);msg('The corpse burns away in a white flash. You feel favored.','good')}advance(100)}
function readTracks(x,y){const t=L.tracks[IX(x,y)];if(!t||t.s==='p'){msg('No tracks here but yours.','hint');return}const age=G.turn-t.t;msg(SP[t.s].n+' tracks, '+(age<20?'very fresh':age<80?'a few hours old':'old')+'.','hint');advance(30)}
function goLink(x,y){const p=G.p;const k=IX(x,y);const d=tdef(x,y);if(d.k==='down'){const lk=L.links[k];if(!lk){msg('It goes nowhere.','warn');return}abstractAll();const lv=ensureLevel(lk);lv.backTo=lv.backTo||{lv:L.id,x,y};const allies=L.cr.filter(c=>(c.ally||c.charm>0)&&dist(c.x,c.y,p.x,p.y)<=3);allies.forEach(c=>{L.cr.splice(L.cr.indexOf(c),1)});p.lv=lv.id;L=lv;const e=lv.exitAt||{x:1,y:1};p.x=e.x;p.y=e.y;allies.forEach(c=>{const sp=passableSpot(p.x,p.y,3);if(sp){c.x=sp.x;c.y=sp.y;L.cr.push(c)}});rebuildOcc();computeFOV();msg(lk.kind==='tomb'?'You descend into the tomb. The air tastes of old salt.':lk.kind==='ruin'?'You climb down into a buried crypt.':'You climb down into darkness. Light a torch.','story');if(lk.kind==='tomb'&&!G.flags.tombOpen)G.flags.tombOpen=G.turn;advance(100)}else if(d.k==='up'){const back=L.backTo;if(!back)return;const allies=L.cr.filter(c=>(c.ally||c.charm>0)&&dist(c.x,c.y,p.x,p.y)<=3);allies.forEach(c=>L.cr.splice(L.cr.indexOf(c),1));const lv=G.levels[back.lv];p.lv=back.lv;L=lv;p.x=back.x;p.y=back.y;allies.forEach(c=>{const sp=passableSpot(p.x,p.y,3);if(sp){c.x=sp.x;c.y=sp.y;L.cr.push(c)}});realizeTick(true);rebuildOcc();computeFOV();msg('You climb back to the surface.','');advance(100)}}
function compass(dx,dy){const ns=dy<-3?'north':dy>3?'south':'';const ew=dx<-3?'west':dx>3?'east':'';return(ns+ew)||'nearby'}
// ===== TRAVEL =====
function ferryOptions(port){const p=G.p;const here=port;return G.sites.filter(s=>(s.type==='port'||s.portLike)&&s.id!==here.id&&s.fac!=='horde'&&seaAnchor(s)).map(s=>{const d=Math.hypot(s.x-here.x,s.y-here.y);const known=s.known;return{s,cost:Math.round(15+d/8),turns:Math.round(d/3),known}}).sort((a,b)=>a.cost-b.cost)}
function takeFerry(o){const p=G.p;if(p.bg==='sailor')o.cost=Math.ceil(o.cost/2);if(p.coins<o.cost)return;p.coins-=o.cost;const n=o.turns;msg('You pay '+o.cost+' coins and board a ship bound for '+o.s.name+'.','hint');abstractAll();const allies=L.cr.filter(c=>c.ally);allies.forEach(c=>L.cr.splice(L.cr.indexOf(c),1));if(p.mount){msg('Your '+MOUNTS[p.mount.s].n+' travels in the hold.','')}passTime(n,true);const ev=R();if(ev<.15){const lost=Math.min(p.coins,ri(5,25));p.coins-=lost;msg('Pirates harried the crossing. You lost '+lost+' coins in the scramble.','warn')}else if(ev<.25){p.hp=Math.max(1,p.hp-ri(3,8));msg('A storm battered the ship. You arrive bruised.','warn')}else msg('The crossing was uneventful.','');const a=blueprint(o.s).pois.pier;const dest=a&&a.length?a[0]:{x:o.s.x,y:o.s.y};const sp=passableSpot(dest.x,dest.y,6)||{x:o.s.x,y:o.s.y};p.x=sp.x;p.y=sp.y;o.s.known=1;realizeTick(true);allies.forEach(c=>{const q=passableSpot(p.x,p.y,3);if(q){c.x=q.x;c.y=q.y;L.cr.push(c)}});rebuildOcc();computeFOV();msg('You arrive at '+o.s.name+' on '+G.conts[o.s.cont].name+'.','story');story('Sailed to '+G.conts[o.s.cont].name+'.',1)}
function passTime(n,abstract){const p=G.p;for(let i=0;i<n&&!G.over;i++){G.turn++;seasonTick();if(i%3===0){p.hunger=clamp(p.hunger-.25,0,100);p.thirst=clamp(p.thirst-.3,0,100)}if(G.turn%5===0)macroTick();if(G.turn%20===0)worldTick();if(G.turn%60===0)weatherTick()}if(p.hunger<10)p.hp=Math.max(1,p.hp-5)}
function journeyTargets(){const p=G.p;const c=contAt(p.x,p.y);if(!c||!L.world)return[];return G.sites.filter(s=>s.cont===c.id&&s.known&&s.type!=='cave'&&dist(s.x,s.y,p.x,p.y)>12&&G.edges.some(e=>e.a===s.id||e.b===s.id))}
function journey(s){const p=G.p;const from=nearestSiteTo(p.x,p.y,c=>G.edges.some(e=>e.a===c.id||e.b===c.id)&&c.cont===s.cont);if(!from){msg('No road leads there from here.','warn');return}const r=route(from.id,s.id);if(!r){msg('No road leads there.','warn');return}if(dist(p.x,p.y,from.x,from.y)>20){msg('Get to a road or settlement first.','warn');return}abstractAll();const allies=L.cr.filter(c=>c.ally);allies.forEach(c=>L.cr.splice(L.cr.indexOf(c),1));let stopped=null;const step=p.mount?3:2;for(let i=0;i<r.length;i+=step){const[x,y]=r[i];p.x=x;p.y=y;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)setSeen(x+dx,y+dy);passTime(p.mount?2:3);const b=G.bands.find(b=>!b.live&&dist(b.x,b.y,x,y)<=6&&(hostileFac(b.fac,'free')||b.kind==='monster')&&b.fac!=='free');if(b&&chance(.5)){stopped=b;break}if(G.over)break}if(!stopped){const sp=passableSpot(s.x,s.y+s.r+1,6)||passableSpot(s.x,s.y,8);if(sp){p.x=sp.x;p.y=sp.y}msg('You arrive at '+s.name+'.','good')}else msg('Your journey is cut short: you run into '+bandDesc(stopped)+'.','bad');realizeTick(true);allies.forEach(c=>{const q=passableSpot(p.x,p.y,3);if(q){c.x=q.x;c.y=q.y;L.cr.push(c)}});rebuildOcc();computeFOV()}
function nearestSiteTo(x,y,f){let b=null,bd=1e9;for(const s of G.sites){if(f&&!f(s))continue;const d=dist(s.x,s.y,x,y);if(d<bd){bd=d;b=s}}return b}
